#!/usr/bin/env python3
"""Materialize V51 51072405 state/trend/failure research upgrade."""
from __future__ import annotations
import base64,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAYLOADS={
'training/v51_state_trend_failure_audit.py':'',
'tools/v51_state_trend_failure_harness.py':'',
'docs/V51_STATE_TREND_SELECTIVE_UPGRADE_51072405.md':'',
}
def main():
    for relative,payload in PAYLOADS.items():
        target=ROOT/relative
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_text(zlib.decompress(base64.b64decode(payload)).decode('utf-8'),encoding='utf-8')
    bootstrap=ROOT/'reports/V51_BOOTSTRAP_PATHS.txt'
    existing=[x.strip() for x in bootstrap.read_text('utf-8').splitlines() if x.strip()] if bootstrap.exists() else []
    for relative in PAYLOADS:
        if relative not in existing: existing.append(relative)
    bootstrap.parent.mkdir(parents=True,exist_ok=True)
    bootstrap.write_text('\n'.join(existing)+'\n',encoding='utf-8')
    print('V51_STATE_TREND_FAILURE_51072405_MATERIALIZED=%d'%len(PAYLOADS))
if __name__=='__main__':main()
